        } else {
            executor = resolver.getPropertyGet(this, obj, identifier);
        }
        if (executor != null) {
            return executor;
        }
    }

    // Handling unsolvable properties
    if (executor == null && property != null) {
        executor = new UnsolvablePropertyGet(is, claz, property);
    }

    return executor;
